  const hk_real t5 = t2 * t2;
  const hk_real d5 = (HK_LIT(2) * t2 * d2);
  const hk_real t6 = (t4 + t5);
  const hk_real d6 = (d4 + d5);
  const hk_real t7 = HK_LIT(2);
  const hk_real d7 = HK_LIT(0);
  const hk_real t8 = (t0 / t7);
  const hk_real d8 = ((d0 * t7 - t0 * d7) / (t7 * t7));
