  hk_real lo3, hi3, L3;
  hk_bx_trig(0, lo0, hi0, L0, &lo3, &hi3, &L3);
  hk_real lo4, hi4, L4;
  hk_bx_mul(lo3, hi3, L3, lo1, hi1, L1, &lo4, &hi4, &L4);
  hk_real lo5, hi5, L5;
  hk_bx_trig(1, lo0, hi0, L0, &lo5, &hi5, &L5);
  hk_real lo6, hi6, L6;
  hk_bx_mul(lo5, hi5, L5, lo2, hi2, L2, &lo6, &hi6, &L6);
  hk_real lo7, hi7, L7;
  hk_bx_sub(lo4, hi4, L4, lo6, hi6, L6, &lo7, &hi7, &L7);
  hk_real lo8, hi8, L8;
  hk_bx_mul(lo5, hi5, L5, lo1, hi1, L1, &lo8, &hi8, &L8);
  hk_real lo9, hi9, L9;
  hk_bx_mul(lo3, hi3, L3, lo2, hi2, L2, &lo9, &hi9, &L9);
  hk_real lo10, hi10, L10;
  hk_bx_add(lo8, hi8, L8, lo9, hi9, L9, &lo10, &hi10, &L10);
  hk_olo[0] = lo7; hk_ohi[0] = hi7; hk_oL[0] = L7;
