  const hk_real d0 = hk_dx[0];
  const hk_real t1 = delta;
  const hk_real d1 = hk_dx[1];
  const hk_real t2 = rw;
  const hk_real d2 = hk_dx[2];
  const hk_real t3 = HK_LIT(2);
  const hk_real d3 = HK_LIT(0);
